Mini game **kumpulkan bintang** (keyboard + sentuh). Run di studio:

```html
<!doctype html>
<html lang="id"><head>
<meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Bintang</title>
<style>
body{margin:0;background:#0b1220;color:#e8f1ff;font-family:system-ui;user-select:none;touch-action:none}
#ui{position:fixed;top:12px;left:12px;z-index:2}
canvas{display:block;width:100vw;height:100vh}
</style></head><body>
<div id="ui">Skor: <span id="s">0</span></div>
<canvas id="c"></canvas>
<script>
const c=document.getElementById('c'),x=c.getContext('2d');
let W,H,score=0,px,py,stars=[];
function resize(){W=c.width=innerWidth;H=c.height=innerHeight;px=W/2;py=H-60}
resize();addEventListener('resize',resize);
function spawn(){stars.push({x:Math.random()*W,y:-10,v:2+Math.random()*3})}
setInterval(spawn,500);
const keys={};
addEventListener('keydown',e=>keys[e.key]=true);
addEventListener('keyup',e=>keys[e.key]=false);
addEventListener('pointermove',e=>{px=e.clientX;py=e.clientY});
function loop(){
  x.fillStyle='#0b1220';x.fillRect(0,0,W,H);
  if(keys.ArrowLeft||keys.a)px-=6; if(keys.ArrowRight||keys.d)px+=6;
  if(keys.ArrowUp||keys.w)py-=6; if(keys.ArrowDown||keys.s)py+=6;
  px=Math.max(20,Math.min(W-20,px)); py=Math.max(20,Math.min(H-20,py));
  x.fillStyle='#5eb0ff';x.beginPath();x.arc(px,py,14,0,6.28);x.fill();
  for(let i=stars.length-1;i>=0;i--){
    const s=stars[i]; s.y+=s.v;
    x.fillStyle='#ffd76a';x.fillRect(s.x,s.y,10,10);
    if(Math.hypot(s.x-px,s.y-py)<20){stars.splice(i,1);score++;document.getElementById('s').textContent=score}
    else if(s.y>H)stars.splice(i,1);
  }
  requestAnimationFrame(loop);
}
loop();
</script></body></html>
```
